int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    struct sock *sk = sock->sk;
    int error, len = 0;
    long timeo;

    if (sock->file->f_flags & O_NONBLOCK || (flags & MSG_DONTWAIT))
        timeo = 0;
    else
        timeo = sock_rcvtimeo(sk);

    lock_sock(sk);

    if (sk->sk_shutdown & RCV_SHUTDOWN)
        error = 0;
    else if (sk->sk_state != TCP_ESTABLISHED) {
        error = -ENOTCONN;
        goto out;
    } else {
        error = -EAGAIN;
        if (!skb_queue_empty(&sk->sk_receive_queue))
            error = 0;
        else if (timeo == 0)
            goto out;

        while (error) {
            if (signal_pending(current)) {
                error = -ERESTARTSYS;
                break;
            }

            error = wait_for_event(sk->sk_sleep, timeo,
                                     !skb_queue_empty(&sk->sk_receive_queue),
                                     error);
            if (error > 0)
                error = 0;
            else
                break;
        }

        if (error)
            goto out;
    }

    len = skb_recv_datagram(sk, flags, &error);
    if (len < 0)
        goto out;

    if (m) {
        struct sk_buff *skb = skb_peek(&sk->sk_receive_queue);
        if (skb && !(flags & MSG_PEEK))
            skb_unlink(skb, &sk->sk_receive_queue);

        if (flags & MSG_TRUNC)
            len = skb->len;
        else if (len > buf_len) {
            len = -EMSGSIZE;
            goto out;
        }

        if (skb->len > 0) {
            error = skb_copy_datagram_msg(skb, 0, m, 0, len);
            if (error < 0) {
                len = error;
                goto out;
            }
        }

        m->msg_flags = 0;
        if (sk->sk_state == TCP_CLOSE)
            m->msg_flags |= MSG_EOF;
    }

    error = len;
    if (len <= 0)
        error = 0;

out:
    release_sock(sk);
    return error;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int ret;
    struct sock *sk = sock->sk;
    size_t copied = 0;

    if (!sk)
        return -EINVAL;

    lock_sock(sk);

    if ((sk->sk_state == TCP_LISTEN))
        ret = -OPNOTSUPP;
    else {
        while (sk->sk_receive_queue.empty && !(flags & MSG_DONTWAIT)) {
            if (signal_pending(current)) {
                ret = -ERESTARTSYS;
                break;
            }
            if (sk->sk_state == TCP_CLOSE) {
                ret = -ENOTCONN;
                break;
            }
            wait_event_interruptible(sk->sk_receive_wait, !sk->sk_receive_queue.empty);
        }

        if (ret)
            goto out;

        if (sk->sk_receive_queue.empty) {
            ret = -EAGAIN;
            goto out;
        }

        struct sk_buff *skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb) {
            ret = -EAGAIN;
            goto out;
        }

        copied = skb->len;
        if (copied > buf_len)
            copied = buf_len;

        if (memcpy_to_msg(m, skb->data, copied)) {
            ret = -EFAULT;
            goto out_skb;
        }

        if (skb->len > copied)
            sk->sk_receive_queue.head = skb->len - copied;
        else
            skb_queue_head(&sk->sk_receive_queue);

        if (m->msg_name)
            memcpy(m->msg_name, &sk->sk_peer_addr, sk->sk_addr_len);

        if (m->msg_controllen) {
            struct cmsghdr *cmsg;
            cmsg = CMSG_FIRSTHDR(m);
            cmsg->cmsg_level = SOL_SOCKET;
            cmsg->cmsg_type = SCM_TIMESTAMP;
            cmsg->cmsg_len = CMSG_LEN(sizeof(struct timeval));
            memcpy(CMSG_DATA(cmsg), &sk->sk_rx_time, sizeof(struct timeval));
        }

        ret = copied;
        if (sk->sk_state == TCP_CLOSE)
            sock_shutdown(sk, SHUT_RD);

        kfree_skb(skb);
    }

out_skb:
    sock_put(sk);
out:
    release_sock(sk);
    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int ret;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;

    if (!sock || !m || !sk)
        return -EINVAL;

    lock_sock(sk);

    if (sk->sk_state == TCP_LISTEN) {
        release_sock(sk);
        return -ENOTCONN;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        ret = wait_for_message(sk, flags);
        if (ret <= 0) {
            release_sock(sk);
            return ret;
        }
        skb = skb_dequeue(&sk->sk_receive_queue);
    }

    m->msg_name = (void *)&skb->skb_data;
    m->msg_namelen = sizeof(skb->skb_data);

    if (skb->ip_summed != CHECKSUM_UNNECESSARY)
        m->msg_flags |= MSG_CTRUNC;

    ret = skb_copy_datagram_iovec(skb, 0, m->msg_iov, min(skb->len, buf_len));
    if (ret < 0) {
        kfree_skb(skb);
        release_sock(sk);
        return ret;
    }

    skb_queue_head(&sk->sk_receive_queue, skb);
    m->msg_len = min(skb->len, buf_len);

    if (skb->len <= 0) {
        release_sock(sk);
        return -EFAULT;
    }

    sk->sk_state = TCP_ESTABLISHED;
    release_sock(sk);

    return m->msg_len;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;
    struct sk_buff *skb;
    size_t offset;

    if (!sock || !m)
        return -EINVAL;

    lock_sock(sk);

    while (1) {
        if (sk->sk_state == TCP_CLOSE) {
            err = -ENOTCONN;
            goto out;
        }

        if (sk->sk_err) {
            err = -sk->sk_err;
            sk->sk_err = 0;
            goto out;
        }

        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb) {
            if (flags & MSG_DONTWAIT) {
                err = -EAGAIN;
                goto out;
            }
            continue; /* Wait for data to arrive */
        }

        offset = 0;

        while (offset < skb->len) {
            size_t copy = skb->len - offset;
            if (copy > buf_len)
                copy = buf_len;

            if (!copy) {
                /* Partial message, keep the skb in the queue for next time */
                skb_queue_head(&sk->sk_receive_queue, skb);
                break;
            }

            if (copy_from_skb(m->msg_control, skb, offset, copy)) {
                skb_queue_head(&sk->sk_receive_queue, skb);
                err = -EFAULT;
                goto out;
            }

            offset += copy;
            copied += copy;
            buf_len -= copy;
        }

        if (skb->len == offset)
            kfree_skb(skb);
        else {
            skb_pull(skb, offset);
            skb_queue_head(&sk->sk_receive_queue, skb);
        }

        if (copied > 0)
            break;
    }

out:
    release_sock(sk);
    return (copied > 0) ? copied : err;
}

int receive_socket_message(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;

    lock_sock(sk);

    if (!sock->sk->sk_receive_queue) {
        release_sock(sk);
        return -EAGAIN;
    }

    skb = skb_peek(&sock->sk->sk_receive_queue);
    if (!skb) {
        release_sock(sk);
        return -EAGAIN;
    }

    m->msg_name = (void *)&skb->cb;
    m->msg_namelen = sizeof(struct sockaddr);
    m->msg_control = NULL;
    m->msg_controllen = 0;

    if (skb->len > buf_len) {
        ret = -EMSGSIZE;
        goto out;
    }

    if (skb_copy_datagram_to_iter(skb, 0, &m->msg_iter, skb->len)) {
        ret = -EFAULT;
        goto out;
    }

    ret = skb->len;

    if (skb->pkt_type == PACKET_ERR) {
        ret = -EFAULT;
        goto out;
    }

    __skb_unlink(skb, &sock->sk->sk_receive_queue);
    kfree_skb(skb);

out:
    release_sock(sk);
    return ret;
}
